PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',github_url TEXT NOT NULL DEFAULT '',path TEXT NOT NULL DEFAULT 'modernization',stage TEXT NOT NULL DEFAULT 'discovery',repo_name TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contexts (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,kind TEXT NOT NULL,content TEXT NOT NULL,source TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,goal TEXT NOT NULL,acceptance TEXT NOT NULL,scope TEXT NOT NULL,context_ids TEXT NOT NULL,assignments TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),project_id TEXT NOT NULL REFERENCES projects(id),role TEXT NOT NULL,instruction TEXT NOT NULL,repo_name TEXT NOT NULL,base_commit TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempt INTEGER NOT NULL DEFAULT 1,runner_id TEXT,lease_token TEXT,lease_until INTEGER,head_commit TEXT,diff TEXT,tests TEXT,summary TEXT,review_note TEXT,packet_json TEXT NOT NULL,created_at TEXT NOT NULL,started_at TEXT,finished_at TEXT,reviewed_at TEXT);
CREATE INDEX IF NOT EXISTS runs_status ON runs(status,created_at);
CREATE TABLE IF NOT EXISTS runners (id TEXT PRIMARY KEY,last_seen TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY,action TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
